# update transform reflect only into zero; across horizontal and vertical partitions with max d=5
code='''def transform(grid):
    out=[r[:] for r in grid]
    h,w=len(grid),len(grid[0])
    def mirror(axis, sep):
        limit=5
        for d in range(1,limit+1):
            a,b=sep-d,sep+d
            if a<0 or b>= (h if axis==0 else w): continue
            if axis==0:
                for c in range(w):
                    if grid[a][c] not in (0,8) and out[b][c]==0: out[b][c]=grid[a][c]
                    if grid[b][c] not in (0,8) and out[a][c]==0: out[a][c]=grid[b][c]
            else:
                for r in range(h):
                    if grid[r][a] not in (0,8) and out[r][b]==0: out[r][b]=grid[r][a]
                    if grid[r][b] not in (0,8) and out[r][a]==0: out[r][a]=grid[r][b]
    for r in range(h):
        if all(x==8 for x in grid[r]): mirror(0,r)
    for c in range(w):
        if all(grid[r][c]==8 for r in range(h)): mirror(1,c)
    return out
'''
