# generate block-propagation program + output
code='''def transform(grid):
    out=[r[:] for r in grid]
    rb=[0,6,12,18]; cb=[0,6,12,18]
    for br in (0,2):
      for bc in (0,2):
        sources=[]
        for rr in (br,br+1):
          for cc in (bc,bc+1):
            pat={(r-rb[rr],c-cb[cc],grid[r][c]) for r in range(rb[rr],min(rb[rr]+5,len(grid))) for c in range(cb[cc],min(cb[cc]+5,len(grid[0]))) if grid[r][c] not in (0,8)}
            if pat: sources.append((rr,cc,pat))
        for rr in (br,br+1):
          for cc in (bc,bc+1):
            for sr,sc,pat in sources:
              for y,x,v in pat:
                yy=4-y if rr!=sr else y; xx=4-x if cc!=sc else x
                r,c=rb[rr]+yy,cb[cc]+xx
                if r<len(out) and c<len(out[0]) and out[r][c]==0: out[r][c]=v
    return out
'''
